    Bug 1983842 - [Thunderbird Telemetry] AH: Add glean probe for account hub account creations. r=vineet,tobyp


    Record an event with an account is successfully created in account hub, along with numbers of address books and calendars that could be synced.

    Differential Revision: https://phabricator.services.mozilla.com/D305818

diff --git a/mail/components/accountcreation/views/email.mjs b/mail/components/accountcreation/views/email.mjs
index 0dcf121b899..e0a6b60943e 100644
--- a/mail/components/accountcreation/views/email.mjs
+++ b/mail/components/accountcreation/views/email.mjs
@@ -1612,6 +1612,12 @@ class AccountHubEmail extends HTMLElement {
       this.abortable?.signal?.throwIfAborted();
       this.abortable = null;

+      Glean.mail.accountHubFinished.record({
+        account_type: this.#currentConfig.incoming.type,
+        address_books: syncAccounts.addressBooks.length,
+        calendars: syncAccounts.calendars.length,
+      });
+
       // If there are no syncable accounts, we should go to the email added
       // success view.
       if (
@@ -1632,6 +1638,14 @@ class AccountHubEmail extends HTMLElement {
         });
       }
     } catch (error) {
+      gAccountSetupLogger.warn("Fetch sync accounts FAILED!", error);
+
+      Glean.mail.accountHubFinished.record({
+        account_type: this.#currentConfig.incoming.type,
+        address_books: 0,
+        calendars: 0,
+      });
+
       // If there's an error, we should just move to the success subview.
       await this.#initUI("emailAddedSuccessSubview");
       this.#currentSubview.setState(this.#currentConfig);
diff --git a/mail/metrics.yaml b/mail/metrics.yaml
index 368ce3ddc3f..9f4e15126fc 100644
--- a/mail/metrics.yaml
+++ b/mail/metrics.yaml
@@ -684,3 +684,29 @@ mail:
     notification_emails:
       - telemetry-client-dev@thunderbird.net
     expires: never
+
+  account_hub_finished:
+    type: event
+    description: >
+      Tracks each time account setup is finished
+    bugs:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1983842
+    data_reviews:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1983842#cXXX
+    data_sensitivity:
+      - technical
+    notification_emails:
+      - telemetry-client-dev@thunderbird.net
+    expires: never
+    extra_keys:
+      account_type:
+        description: Type of mail account set up.
+        type: string
+      address_books:
+        description: Number of address books to sync found.
+        type: quantity
+        unit: items
+      calendars:
+        description: Number of calendars to sync found.
+        type: quantity
+        unit: items
